    {"id":"hippocrates","title":{"zh":"体液说与气质","en":"Humoral Theory and Temperament"},"year":-400,"when":{"zh":"约公元前 400 年"},"summary":{"zh":"希波克拉底学派用血液、黏液、黄胆汁、黑胆汁四种体液解释性情与疾病，后来的“四气质”说是气质类型学的源头；艾森克曾把自己的维度与四气质相对照。"},"threads":["difference","clinical","bio"],"to":"factor-personality","people":["hippocrates-of-cos"],"legacy":{"zh":"“多血质、胆汁质”等气质名称仍在日常说话和一些流行的性格测试里出现；严肃的人格研究早已改用可测量的维度，如大五人格，但“人的性情有稳定的类型差异”这一想法由此而来。"}},
    {"id":"buddhist","title":{"zh":"佛教的禅修与心识分析","en":"Buddhist Meditation and Analysis of Mind"},"year":-450,"when":{"zh":"约公元前 5 世纪起"},"summary":{"zh":"以系统的内观训练观察注意、感受与念头的生灭，并发展出对心理现象的细致分类；当代正念课程与接纳取向疗法从中借用了练习。"},"threads":["clinical","humanistic"],"to":"mbsr","people":[],"legacy":{"zh":"正念减压、正念认知疗法、接纳承诺疗法等把“观察当下体验”的训练带进了医院和诊所；这些课程多把宗教内容去掉，只保留练习。"}},
    {"id":"aristotle","title":{"zh":"亚里士多德《论灵魂》","en":"Aristotle's De Anima"},"year":-350,"when":{"zh":"约公元前 350 年"},"summary":{"zh":"把灵魂当作生命体的功能来研究；在《论记忆与回忆》里提出观念靠相似、对比、接近而联结，这是联想主义的源头。"},"threads":["cognition","behavior"],"people":[],"legacy":{"zh":"联想的三条原则（相似、对比、接近）仍是教科书讲联想记忆的起点；“灵魂是生命体的功能”的看法与今天的功能主义、心灵哲学的讨论相呼应。"}},
    {"id":"confucian-daoist","title":{"zh":"儒道的心性修养","en":"Confucian and Daoist Self-Cultivation"},"year":-300,"when":{"zh":"先秦"},"summary":{"zh":"把人格看作在关系与修养中养成的过程，而不是孤立个体的内在属性，这是华人本土心理学常常回溯的思想资源。"},"threads":["social","humanistic"],"to":"indigenous","people":[],"legacy":{"zh":"华人本土心理学用“关系”“面子”“修养”等概念建立自己的理论，并常与西方偏重个人的心理学对照。"}},
    {"id":"stoic","title":{"zh":"斯多葛学派","en":"Stoicism"},"year":100,"when":{"zh":"公元前 3 世纪至公元 2 世纪"},"summary":{"zh":"爱比克泰德说，困扰人的不是事情本身，而是人对事情的看法；艾利斯和贝克都明确引用过这一思想，作为认知治疗的哲学先声。"},"threads":["clinical","humanistic"],"to":"cognitive-therapies","people":["epictetus"],"legacy":{"zh":"认知行为治疗里“想法影响情绪”的基本思路，常被追溯到这一传统；创始人艾利斯与贝克都引用过斯多葛学派的这类说法。"}},
    {"id":"avicenna","title":{"zh":"伊本·西那《医典》","en":"Avicenna's Canon of Medicine"},"year":1025,"when":{"zh":"1025 年"},"summary":{"zh":"在医学体系中描述并分类了忧郁、躁狂、恋爱病等心理病症，并把它们与身体状态联系起来，是欧洲中世纪医学的教科书。"},"threads":["clinical","bio"],"to":"nosology","people":["ibn-sina"],"legacy":{"zh":"《医典》在欧洲与伊斯兰世界作为医学教材使用了数百年；其中对忧郁、躁狂等的描述，是精神病学史上较早的系统分类，今天主要作为医学史与精神病学史的参考。"}},
    {"id":"descartes","title":{"zh":"笛卡尔的身心二元论","en":"Descartes' Mind-Body Dualism"},"year":1641,"when":{"zh":"1641 年"},"summary":{"zh":"《第一哲学沉思集》把心与身分成两种实体，留下“两者如何相互作用”的问题，此后的神经科学与心灵哲学都在回应它。"},"threads":["bio","cognition"],"people":[],"legacy":{"zh":"“心与身如何相互作用”的问题今天仍以意识的“困难问题”等形式出现在心灵哲学和神经科学中；达马西奥的《笛卡尔的错误》就以批评这一二分为题。"}},
    {"id":"locke","title":{"zh":"经验论与联想主义","en":"Empiricism and Associationism"},"year":1690,"when":{"zh":"1690 年"},"summary":{"zh":"洛克《人类理解论》主张心灵起初如白板，观念来自经验及其联结；休谟、密尔等人把联结发展成联想主义，是行为主义学习观的祖先。"},"threads":["behavior","cognition"],"to":"law-of-effect","people":["john-locke"],"legacy":{"zh":"“经验塑造心灵”的想法体现在行为主义与联结主义里：联想进入学习理论，神经网络则靠联结强度的变化来学习；“白板”之争至今仍出现在先天与后天的讨论中。"}},
    {"id":"rousseau","title":{"zh":"卢梭的儿童观","en":"Rousseau's View of Childhood"},"year":1762,"when":{"zh":"1762 年"},"summary":{"zh":"《爱弥儿》主张童年有自身的阶段与价值，儿童不是“小大人”；这一思想是此后儿童研究与发展阶段理论的起点之一。"},"threads":["development"],"to":"child-study","people":["jean-jacques-rousseau"],"legacy":{"zh":"“儿童不是缩小的成人，童年有自己的阶段”成为发展心理学的基本前提，今天的幼儿教育理念里还能看到它。"}},
    {"id":"mesmer","title":{"zh":"催眠术的前身","en":"Mesmerism"},"year":1774,"when":{"zh":"1774 年起"},"summary":{"zh":"梅斯梅尔的“动物磁气”被科学委员会否定，但暗示的效果被注意到；布雷德在 1843 年改称“催眠”，开启了对暗示与意识分离的研究。"},"threads":["depth","clinical"],"to":"dissociation","people":["franz-mesmer"],"legacy":{"zh":"催眠今天仍用于疼痛管理和部分心理治疗；1784 年法国王家委员会对“动物磁气”的检验，常被视为早期带有盲法的对照实验，使“暗示”成为后来安慰剂研究的主题。"}},
    {"id":"kant","title":{"zh":"康德的先验范畴","en":"Kant's A Priori Categories"},"year":1781,"when":{"zh":"1781 年"},"summary":{"zh":"《纯粹理性批判》主张心灵用自带的结构（时间、空间、因果）组织经验；这一想法后来影响了格式塔与建构论的发展观。"},"threads":["cognition","development"],"to":"gestalt","people":["immanuel-kant"],"legacy":{"zh":"“心灵自带组织经验的结构”的想法，常被拿来与皮亚杰的“图式”和乔姆斯基的先天语法相比；格式塔心理学也常追溯到这一传统。"}},
    {"id":"pinel","title":{"zh":"精神病院改革","en":"Asylum Reform"},"year":1793,"when":{"zh":"1793 年"},"summary":{"zh":"皮内尔在巴黎比塞特医院推行“道德治疗”，把疯癫看作可以治疗的疾病，要求对病人观察、描述与分类；解开病人锁链一事的细节有传说成分。"},"threads":["clinical"],"to":"nosology","people":["philippe-pinel"],"legacy":{"zh":"“把精神病人当作患者而不是罪人”的原则，是现代精神卫生服务和去机构化讨论的起点；不过“解开铁链”的著名场景与事实有出入，真正动手的更多是看守普桑。"}},
    {"id":"gall","title":{"zh":"颅相学","en":"Phrenology"},"year":1810,"when":{"zh":"1810 年"},"summary":{"zh":"加尔认为不同心理功能位于不同脑区；用头骨形状推断性格是伪科学，但“功能定位”的想法被保留了下来。"},"threads":["bio","difference"],"to":"localization","people":["franz-gall"],"legacy":{"zh":"颅相学本身已被否定，但“不同脑区负责不同功能”这一想法在布洛卡之后得到证实，今天的脑成像研究仍在绘制功能分区。"}},
    {"id":"schopenhauer","title":{"zh":"无意识的意志","en":"The Unconscious Will"},"year":1819,"when":{"zh":"1819 年"},"summary":{"zh":"叔本华《作为意志和表象的世界》：驱动人的是非理性的意志；哈特曼 1869 年的《无意识哲学》进一步发展，成为弗洛伊德与荣格所处的思想背景。"},"threads":["depth"],"to":"psychoanalysis","people":["arthur-schopenhauer"],"legacy":{"zh":"弗洛伊德自己承认叔本华早已说过压抑与无意识；“人并不总知道自己的动机”今天在内隐认知研究里以另一种方式出现。"}},
    {"id":"weber","title":{"zh":"韦伯定律","en":"Weber's Law"},"year":1834,"when":{"zh":"1834 年"},"summary":{"zh":"韦伯发现，刚能察觉的差别与刺激强度成固定比例，感觉第一次被精确地测量，费希纳据此建立了心理物理学。"},"threads":["cognition"],"to":"psychophysics","people":["e-h-weber"],"legacy":{"zh":"“最小可觉差”与韦伯分数仍用于感知实验与产品设计，例如判断两种亮度、两种声音的差别是否会被察觉。"}},
    {"id":"quetelet","title":{"zh":"社会统计与“平均人”","en":"Social Statistics and the Average Man"},"year":1835,"when":{"zh":"1835 年"},"summary":{"zh":"凯特勒《论人》把正态分布用于人的身高、犯罪率等特征，提出“平均人”；高尔顿后来由此转向研究与平均的偏离。"},"threads":["difference","social"],"to":"individual-differences","people":["adolphe-quetelet"],"legacy":{"zh":"“平均人”成为用统计描述人群的起点；今天的体重指数（BMI）又叫“凯特勒指数”。"}},
    {"id":"kierkegaard","title":{"zh":"存在哲学的开端","en":"Beginnings of Existential Philosophy"},"year":1844,"when":{"zh":"1844 年"},"summary":{"zh":"克尔凯郭尔《焦虑的概念》：焦虑来自人面对自由与可能性时的眩晕，而不只是对具体危险的恐惧。"},"threads":["humanistic"],"to":"existential","people":["soren-kierkegaard"],"legacy":{"zh":"“焦虑来自自由”的论点被罗洛·梅等存在治疗者引用，存在取向的心理治疗至今用它理解焦虑。"}},
    {"id":"helmholtz","title":{"zh":"感官生理学","en":"Sensory Physiology"},"year":1850,"when":{"zh":"1850 年"},"summary":{"zh":"赫尔姆霍兹测出神经传导速度，说明心理过程需要时间、可以测量；他还提出知觉包含“无意识推理”，给冯特的实验室提供了方法与问题。"},"threads":["bio","cognition"],"to":"experimental","people":["hermann-helmholtz"],"legacy":{"zh":"神经传导速度的测量使反应时研究成为可能，认知实验至今把反应时当作基本指标；他的“无意识推论”知觉观也被预测加工重新提起。"}},
    {"id":"darwin","title":{"zh":"进化论","en":"Theory of Evolution"},"year":1859,"when":{"zh":"1859 年"},"summary":{"zh":"《物种起源》；1872 年《人和动物的表情》把情绪放进演化的连续谱。适应、个体差异与连续性成为多个脉络的共同背景。"},"threads":["bio","difference","development"],"to":"functionalism","people":["charles-darwin"],"legacy":{"zh":"进化心理学、动物行为学和情绪的跨物种比较，都以《物种起源》与《人和动物的表情》为起点。"}},
    {"id":"volkerpsychologie","title":{"zh":"民族心理学","en":"Volkerpsychologie"},"year":1860,"when":{"zh":"1860 年"},"summary":{"zh":"拉扎勒斯与施泰因塔尔创办杂志，研究语言、习俗与集体心理；冯特晚年的十卷《民族心理学》继承了这一路线。"},"threads":["social"],"to":"crowd","people":["moritz-lazarus"],"legacy":{"zh":"文化心理学以及语言与思维关系的研究，可追溯到把“民族心理”作为研究对象的这一传统；冯特晚年的十卷《民族心理学》也属此列。"}}
